files.content:
:host {
  display: block;
  min-inline-size: 0;
  max-inline-size: 100%;
}

.table-toolbar {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  inline-size: 100%;
  min-inline-size: 0;
  gap: var(--dimension-space-100);
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}

.table-toolbar::-webkit-scrollbar {
  display: none;
}

.table-toolbar__start,
.table-toolbar__search,
.table-toolbar__main,
.table-toolbar__leading,
.table-toolbar__trailing {
  display: flex;
  align-items: center;
  min-inline-size: 0;
  gap: var(--dimension-space-100);
}

.table-toolbar__start {
  flex: 0 1 var(--dimension-menu-width-xs);
  max-inline-size: var(--dimension-menu-width-xs);
}

.table-toolbar__rule {
  flex: 0 0 auto;
}

.table-toolbar__main {
  flex: 1 1 auto;
  min-inline-size: min-content;
}

.table-toolbar__search {
  flex: 0 1 var(--dimension-panel-width-xs);
  max-inline-size: var(--dimension-panel-width-xs);
}

:host(:not(:has([slot='search']))) .table-toolbar__search {
  display: none;
}

:host(:not(:has([slot='start']))) .table-toolbar__start,
:host(:not(:has([slot='start']))) .table-toolbar__rule {
  display: none;
}

.table-toolbar__leading {
  flex: 1 0 auto;
}

.table-toolbar__trailing {
  flex: 0 0 auto;
  margin-inline-start: auto;
}

.table-toolbar__trailing > *,
.table-toolbar ds-filter-menu,
.table-toolbar ds-select,
.table-toolbar ds-table-sort {
  max-inline-size: var(--dimension-menu-width-xs);
  --ds-choice-popup-min-inline-size: var(--dimension-menu-width-xs);
}

.table-toolbar__start slot,
.table-toolbar__search slot,
.table-toolbar__leading slot,
.table-toolbar__trailing slot {
  display: contents;
}

import { Component, Element, h, Host, Prop } from '@stencil/core';

const CAPTION_CONTROL_SELECTOR = 'ds-filter-menu, ds-select';

@Component({
  tag: 'ds-table-toolbar',
  styleUrl: 'TableToolbar.css',
  scoped: true,
})
export class TableToolbar {
  @Element() private el!: HTMLElement;

  /** Accessible name for the grouped table controls. */
  @Prop() label: string = 'Table controls';

  private captionControlObserver: MutationObserver | undefined;

  componentDidLoad(): void {
    this.connectCaptionControlObserver();
  }

  disconnectedCallback(): void {
    this.captionControlObserver?.disconnect();
  }

  render() {
    return (
      <Host>
        <div class="table-toolbar" role="toolbar" aria-label={this.label}>
          <div class="table-toolbar__start">
            <slot name="start" />
          </div>
          <ds-divider class="table-toolbar__rule" orientation="vertical" length="32px" />
          <div class="table-toolbar__main">
            <div class="table-toolbar__search">
              <slot name="search" />
            </div>
            <div class="table-toolbar__leading">
              <slot name="leading" />
            </div>
            <div class="table-toolbar__trailing">
              <slot name="trailing" />
            </div>
          </div>
        </div>
      </Host>
    );
  }

  private connectCaptionControlObserver(): void {
    if (this.captionControlObserver || typeof MutationObserver === 'undefined') return;
    this.captionControlObserver = new MutationObserver(this.syncCaptionControls);
    this.captionControlObserver.observe(this.el, { childList: true, subtree: true });
    this.syncCaptionControls();
  }

  private syncCaptionControls = () => {
    for (const control of this.el.querySelectorAll<
      HTMLElement & { collapseLabel?: boolean }
    >(CAPTION_CONTROL_SELECTOR)) {
      if (control.closest('ds-table-saved-views')) continue;
      if (control.collapseLabel) continue;
      control.collapseLabel = true;
    }
  };
}
